function subarraysWithMoreOnesThanZeroes(nums) {
  const MOD = 1_000_000_007;
  const n = nums.length;
  const count = new Array(2 * n + 1).fill(0);
  let prefix = n;
  count[prefix] = 1;
  let smaller = 0;
  let answer = 0;

  for (const num of nums) {
    if (num === 1) {
      smaller += count[prefix];
      prefix++;
    } else {
      prefix--;
      smaller -= count[prefix];
    }
    answer = (answer + smaller) % MOD;
    count[prefix]++;
  }
  return answer;
}

