function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const pick = rand();
  // Vary how often a 1 appears so long runs, balanced arrays and lopsided ones all show up.
  const chance = pick < 0.15 ? 0.05 : pick < 0.3 ? 0.95 : 0.25 + rand() * 0.5;
  return [Array.from({ length: n }, () => (rand() < chance ? 1 : 0))];
}
